      const rule = routingRules[prefix];
      const bucket = hashToPercent(req.userId);
      if (bucket < rule.rolloutPercent) {
        return forwardTo(rule.target, req);
      }
      break;
    }
  }
  return forwardTo('legacy-monolith', req);
}

function hashToPercent(userId) {
