import java.util.LinkedHashMap;
import java.util.Map;

class RoutingRule {
    String target;
    int rolloutPercent;

    RoutingRule(String target, int rolloutPercent) {
        this.target = target;
        this.rolloutPercent = rolloutPercent;
    }
}

class Router {
    private final Map<String, RoutingRule> routingRules = new LinkedHashMap<>();

    Router() {
        routingRules.put("/api/search", new RoutingRule("new-search-service", 30));
        routingRules.put("/api/checkout", new RoutingRule("new-checkout-service", 100));
    }

    String routeRequest(String path, String userId) {
        for (Map.Entry<String, RoutingRule> entry : routingRules.entrySet()) {
            String prefix = entry.getKey();
            if (path.startsWith(prefix)) {
                RoutingRule rule = entry.getValue();
                int bucket = hashToPercent(userId);
                if (bucket < rule.rolloutPercent) {
                    return forwardTo(rule.target, path);
                }
                break;
            }
        }
        return forwardTo("legacy-monolith", path);
    }

    private int hashToPercent(String userId) {
        int hash = 0;
        for (char c : userId.toCharArray()) {
            hash = (hash * 31 + c) % 100;
        }
        return hash;
    }

    private String forwardTo(String target, String path) {
        return "Forwarded " + path + " -> " + target;
    }
}

public class Main {
    public static void main(String[] args) {
        Router router = new Router();
        System.out.println(router.routeRequest("/api/search", "user-42"));
        System.out.println(router.routeRequest("/api/checkout", "user-42"));
        System.out.println(router.routeRequest("/api/legacy-report", "user-42"));
    }
}

