class RoutingRule:
    def __init__(self, target, rollout_percent):
        self.target = target
        self.rollout_percent = rollout_percent


class Router:
    def __init__(self):
        self.routing_rules = {
            "/api/search": RoutingRule("new-search-service", 30),
            "/api/checkout": RoutingRule("new-checkout-service", 100),
        }

    def route_request(self, path, user_id):
        for prefix, rule in self.routing_rules.items():
            if path.startswith(prefix):
                bucket = self._hash_to_percent(user_id)
                if bucket < rule.rollout_percent:
                    return self._forward_to(rule.target, path)
                break
        return self._forward_to("legacy-monolith", path)

    @staticmethod
    def _hash_to_percent(user_id):
        hash_value = 0
        for char in str(user_id):
            hash_value = (hash_value * 31 + ord(char)) % 100
        return hash_value

    @staticmethod
    def _forward_to(target, path):
        return f"Forwarded {path} -> {target}"


if __name__ == "__main__":
    router = Router()
    print(router.route_request("/api/search", "user-42"))
    print(router.route_request("/api/checkout", "user-42"))
    print(router.route_request("/api/legacy-report", "user-42"))

