#include <iostream>
#include <string>
#include <map>

class RoutingRule {
public:
    std::string target;
    int rolloutPercent;

    RoutingRule() : rolloutPercent(0) {}
    RoutingRule(std::string target, int rolloutPercent)
        : target(std::move(target)), rolloutPercent(rolloutPercent) {}
};

class Router {
private:
    std::map<std::string, RoutingRule> routingRules;

    static int hashToPercent(const std::string& userId) {
        int hash = 0;
        for (char c : userId) {
            hash = (hash * 31 + static_cast<int>(c)) % 100;
        }
        return hash;
    }

    static std::string forwardTo(const std::string& target, const std::string& path) {
        return "Forwarded " + path + " -> " + target;
    }

public:
    Router() {
        routingRules["/api/search"] = RoutingRule("new-search-service", 30);
        routingRules["/api/checkout"] = RoutingRule("new-checkout-service", 100);
    }

    std::string routeRequest(const std::string& path, const std::string& userId) {
        for (const auto& entry : routingRules) {
            const std::string& prefix = entry.first;
            if (path.compare(0, prefix.size(), prefix) == 0) {
                int bucket = hashToPercent(userId);
                if (bucket < entry.second.rolloutPercent) {
                    return forwardTo(entry.second.target, path);
                }
                break;
            }
        }
        return forwardTo("legacy-monolith", path);
    }
};

int main() {
    Router router;
    std::cout << router.routeRequest("/api/search", "user-42") << std::endl;
    std::cout << router.routeRequest("/api/checkout", "user-42") << std::endl;
    std::cout << router.routeRequest("/api/legacy-report", "user-42") << std::endl;
    return 0;
}
